do $$ declare n int; begin
update lecciones set cuerpo=replace(cuerpo,'tres partículas subatómicas fundamentales.','tres «partículas subatómicas fundamentales» (así las cuenta el autor; la física actual no las cuenta así: protón y neutrón no son fundamentales y hay muchas más).') where id='04f3ea37-1d65-416e-9b3b-5be2ba114f65' and position('tres partículas subatómicas fundamentales.' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: 04f3ea37 cuerpo'; end if;
update lecciones set cuerpo=replace(cuerpo,'solo tres tipos de ADN mitocondrial (M, N, R) se distribuyen en toda la población mundial.','según el autor, solo tres tipos de ADN mitocondrial (M, N, R) se distribuyen en toda la población mundial. (Dato incorrecto: M, N y R son macrohaplogrupos de fuera de África; la humanidad tiene además los linajes africanos L0–L6, los más antiguos, y decenas de haplogrupos.)') where id='04f3ea37-1d65-416e-9b3b-5be2ba114f65' and position('solo tres tipos de ADN mitocondrial (M, N, R) se distribuyen en toda la población mundial.' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: 04f3ea37 cuerpo'; end if;
update lecciones set autocorreccion=replace(autocorreccion,'usar datos científicos reales (tres linajes mitocondriales) para validar','partir de un dato incorrecto (no hay tres linajes mitocondriales, sino decenas de haplogrupos) para validar') where id='04f3ea37-1d65-416e-9b3b-5be2ba114f65' and position('usar datos científicos reales (tres linajes mitocondriales) para validar' in autocorreccion)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: 04f3ea37 autocorreccion'; end if;
update lecciones set autocorreccion=replace(autocorreccion,'La genética de poblaciones explica los tres haplogrupos mitocondriales mediante cuellos de botella evolutivos que no requieren un diluvio literal.','La genética de poblaciones explica la diversidad mitocondrial humana mediante migraciones y cuellos de botella que no requieren un diluvio literal.') where id='04f3ea37-1d65-416e-9b3b-5be2ba114f65' and position('La genética de poblaciones explica los tres haplogrupos mitocondriales mediante cuellos de botella evolutivos que no requieren un diluvio literal.' in autocorreccion)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: 04f3ea37 autocorreccion'; end if;
update lecciones set cuerpo=replace(cuerpo,'Wilson cita datos de 1968 mostrando que el 85% de la población tenía síntomas físicos (palpitaciones, sudoración, pesadillas) compatibles con una impronta de amenaza en el circuito I. Esto significa que la mayoría de personas opera en estado de emergencia neurológica subclínica permanente','Wilson sostiene que muchas personas conservan improntas de amenaza en el circuito I (es una hipótesis suya: no hay una cifra que la respalde). Según ese marco, buena parte de la gente operaría en un estado de emergencia neurológica subclínica permanente') where id='88c0f7d2-59a3-4307-89b7-d0773d747605' and position('Wilson cita datos de 1968 mostrando que el 85% de la población tenía síntomas físicos (palpitaciones, sudoración, pesadillas) compatibles con una impronta de amenaza en el circuito I. Esto significa que la mayoría de personas opera en estado de emergencia neurológica subclínica permanente' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: 88c0f7d2 cuerpo'; end if;
update lecciones set cuerpo=replace(cuerpo,'Navarro distingue entre el paranoico reactivo — cuya desconfianza extrema fue adaptativa en un entorno de amenaza real y se ha generalizado — y el paranoico constitucional — cuya arquitectura de procesamiento social interpreta la amenaza como señal dominante independientemente del entorno. El pronóstico y el manejo son distintos en cada caso.','Esta lección distingue dos formas de paranoia: la reactiva — cuya desconfianza extrema fue adaptativa en un entorno de amenaza real y se ha generalizado — y la constitucional — cuya forma de procesar lo social interpreta la amenaza como señal dominante independientemente del entorno. Es una distinción de la propia lección, no de Navarro.') where id='fc0a61bf-1c39-448f-9208-059e33729816' and position('Navarro distingue entre el paranoico reactivo — cuya desconfianza extrema fue adaptativa en un entorno de amenaza real y se ha generalizado — y el paranoico constitucional — cuya arquitectura de procesamiento social interpreta la amenaza como señal dominante independientemente del entorno. El pronóstico y el manejo son distintos en cada caso.' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: fc0a61bf cuerpo'; end if;
update lecciones set cuerpo=replace(cuerpo,'La extrapolación sistémica que Buzsáki sugiere es poderosa y conecta directamente con el corpus:','Una extrapolación propia de esta lección (no de Buzsáki, cuyo libro no trata de economía) conecta con el corpus como analogía:') where id='ce6e6d1f-d79c-4fb4-b82a-f8898777fe88' and position('La extrapolación sistémica que Buzsáki sugiere es poderosa y conecta directamente con el corpus:' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: ce6e6d1f cuerpo'; end if;
update lecciones set cuerpo=replace(cuerpo,'Alim-Louis Benabid desarrolló la técnica intuyendo que el problema era rítmico antes de que la teoría oscilatoria lo confirmara.','Alim-Louis Benabid desarrolló la técnica en los años ochenta al observar que la estimulación de alta frecuencia suprimía el temblor durante la cirugía; la lectura oscilatoria vino después.') where id='ce6e6d1f-d79c-4fb4-b82a-f8898777fe88' and position('Alim-Louis Benabid desarrolló la técnica intuyendo que el problema era rítmico antes de que la teoría oscilatoria lo confirmara.' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: ce6e6d1f cuerpo'; end if;
update lecciones set cuerpo=replace(cuerpo,'El Alzheimer temprano muestra degradación del ritmo gamma y theta hipocampal meses o años antes de que sean evidentes los déficits cognitivos clínicos — lo que abre una ventana diagnóstica temprana que los biomarcadores químicos no proporcionan con la misma anticipación.','En el Alzheimer se observan alteraciones de los ritmos hipocampales (bien documentadas en modelos animales; en personas, lentificación del EEG) y se investiga si podrían servir como señal temprana; el plazo exacto no está establecido.') where id='ce6e6d1f-d79c-4fb4-b82a-f8898777fe88' and position('El Alzheimer temprano muestra degradación del ritmo gamma y theta hipocampal meses o años antes de que sean evidentes los déficits cognitivos clínicos — lo que abre una ventana diagnóstica temprana que los biomarcadores químicos no proporcionan con la misma anticipación.' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: ce6e6d1f cuerpo'; end if;
update lecciones set aplicacion_practica=replace(aplicacion_practica,'CRISIS FINANCIERAS: La respuesta de QE funcionó como DBS económico','CRISIS FINANCIERAS (analogía propia, no de Buzsáki): la respuesta de QE funcionó, por analogía, como una DBS económica') where id='ce6e6d1f-d79c-4fb4-b82a-f8898777fe88' and position('CRISIS FINANCIERAS: La respuesta de QE funcionó como DBS económico' in aplicacion_practica)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: ce6e6d1f aplicacion_practica'; end if;
update lecciones set cuerpo=replace(cuerpo,'Esta es la base neurológica de por qué el aprendizaje activo supera al pasivo: no es solo psicología motivacional sino electrofisiología.','Una hipótesis atractiva —no demostrada en humanos, y el theta que describe Buzsáki es sobre todo de roedores en movimiento— es que esto contribuya a que el aprendizaje activo supere al pasivo.') where id='7004ee59-93a2-465a-83cb-a8db56830f74' and position('Esta es la base neurológica de por qué el aprendizaje activo supera al pasivo: no es solo psicología motivacional sino electrofisiología.' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: 7004ee59 cuerpo'; end if;
update lecciones set aplicacion_practica=replace(aplicacion_practica,'generan theta porque implican exploración activa. Las revisiones pasivas no.','podrían favorecer estados de theta (hipótesis, no demostrado) porque implican exploración activa.') where id='7004ee59-93a2-465a-83cb-a8db56830f74' and position('generan theta porque implican exploración activa. Las revisiones pasivas no.' in aplicacion_practica)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: 7004ee59 aplicacion_practica'; end if;
update lecciones set aplicacion_practica=replace(aplicacion_practica,'La curiosidad es theta; la confirmación es alpha.','(Es una analogía: no está demostrado que la curiosidad sea theta y la confirmación alpha.)') where id='7004ee59-93a2-465a-83cb-a8db56830f74' and position('La curiosidad es theta; la confirmación es alpha.' in aplicacion_practica)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: 7004ee59 aplicacion_practica'; end if;
update lecciones set conexion_cruzada=replace(conexion_cruzada,'Easter documenta el mecanismo biológico del entorno como calibrador: el sistema nervioso autónomo se regula por co-regulación con otros sistemas nerviosos en el entorno inmediato. No es metáfora — es fisiología.','La literatura sobre co-regulación (Porges, Siegel) documenta que el sistema nervioso autónomo se regula en interacción con otros sistemas nerviosos del entorno inmediato; Easter, por su parte, trata de la incomodidad y los hábitos, no de este mecanismo. No es metáfora — es fisiología.') where id='c553d47f-224c-423e-93d6-7dc6e393ce45' and position('Easter documenta el mecanismo biológico del entorno como calibrador: el sistema nervioso autónomo se regula por co-regulación con otros sistemas nerviosos en el entorno inmediato. No es metáfora — es fisiología.' in conexion_cruzada)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: c553d47f conexion_cruzada'; end if;
update lecciones set cuerpo=replace(cuerpo,'El mecanismo es el priming ambiental: el cerebro','Una explicación posible (síntesis de la lección, no una tesis de Hill) es el priming ambiental: el cerebro') where id='c553d47f-224c-423e-93d6-7dc6e393ce45' and position('El mecanismo es el priming ambiental: el cerebro' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: c553d47f cuerpo'; end if;
update lecciones set cuerpo=replace(cuerpo,'y la fórmula gana sin excepción.','y la fórmula suele ganar.') where id='a0a7429e-d91a-4ac0-9880-7faa5d762f86' and position('y la fórmula gana sin excepción.' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: a0a7429e cuerpo'; end if;
update lecciones set cuerpo=replace(cuerpo,'Los Himba de Namibia no tienen palabra para "sorpresa" en el sentido occidental; distinguen finamente entre tipos de calma que el español agrupa.','Estudios con los Himba de Namibia (Gendron et al., 2014) muestran que no agrupan las expresiones faciales y vocales en las categorías emocionales occidentales «universales», sino que las describen por la conducta que acompañan.') where id='337695f5-b069-41f6-a7b7-1355d7c1fd62' and position('Los Himba de Namibia no tienen palabra para "sorpresa" en el sentido occidental; distinguen finamente entre tipos de calma que el español agrupa.' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: 337695f5 cuerpo'; end if;
update lecciones set cuerpo=replace(cuerpo,'Esta arquitectura, heredada de von Neumann y Morgenstern, es el modelo normativo','Esta arquitectura, que remonta a Savage (la teoría de la utilidad esperada de von Neumann y Morgenstern es de riesgo, sin estados del mundo), es el modelo normativo') where id='ee57b24c-70c6-451a-8023-08e68defb2f7' and position('Esta arquitectura, heredada de von Neumann y Morgenstern, es el modelo normativo' in cuerpo)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: ee57b24c cuerpo'; end if;
update preguntas set explicacion=replace(explicacion,'no fabricar objetivos falsos. Los métodos pueden compartirse; los objetivos se protegen.','no revelar los objetivos finales. Matiz: Greene (ley 3) también recomienda señuelos y cortinas de humo, es decir, sí admite fabricar pistas falsas; la opción D se acerca a su postura más radical.') where id='cdfc06c8-5822-43d4-a359-e2aea26e19a9' and position('no fabricar objetivos falsos. Los métodos pueden compartirse; los objetivos se protegen.' in explicacion)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: cdfc06c8 explicacion'; end if;
update preguntas set explicacion=replace(explicacion,'Si no, necesita más margen.','Si no, necesita más margen. (Es un ejercicio propuesto por la app, no un test de Housel: el libro solo habla de margen de seguridad.)') where id='c31684a4-dd50-4a58-9071-48cd3ef4d787' and position('Si no, necesita más margen.' in explicacion)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: c31684a4 explicacion'; end if;
update preguntas set explicacion=replace(explicacion,'La solución digital tiene el mismo sesgo que Gatto identifica en el homeschooling: funciona bien para quienes ya tienen las condiciones para aprovecharla.','La solución digital funciona mejor para quienes ya tienen las condiciones para aprovecharla (es una crítica externa a Christensen, no una tesis suya).') where id='7a560e19-7e65-4ef3-83e3-9e18b30cd9f0' and position('La solución digital tiene el mismo sesgo que Gatto identifica en el homeschooling: funciona bien para quienes ya tienen las condiciones para aprovecharla.' in explicacion)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: 7a560e19 explicacion'; end if;
